export type AIProviderName = "openai" | "anthropic" | "google";

export interface AIMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface AIRequest {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  metadata?: Record<string, string>;
}

export interface AIResponse {
  provider: AIProviderName;
  model: string;
  content: string;
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    totalTokens?: number;
  };
  latencyMs: number;
}

export type AIErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "UPSTREAM"
  | "NETWORK"
  | "UNKNOWN";

export class AIProviderError extends Error {
  public readonly provider: AIProviderName;
  public readonly code: AIErrorCode;
  public readonly retryable: boolean;
  public readonly cause?: unknown;
  public readonly statusCode?: number;

  constructor(params: {
    provider: AIProviderName;
    code: AIErrorCode;
    message: string;
    retryable: boolean;
    cause?: unknown;
    statusCode?: number;
  }) {
    super(params.message);
    this.name = "AIProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.cause = params.cause;
    this.statusCode = params.statusCode;
  }
}

export class AIOrchestrationError extends Error {
  public readonly errors: AIProviderError[];

  constructor(message: string, errors: AIProviderError[]) {
    super(message);
    this.name = "AIOrchestrationError";
    this.errors = errors;
  }
}

export interface AIProvider {
  name: AIProviderName;
  model: string;
  generate(request: AIRequest, signal?: AbortSignal): Promise<AIResponse>;
}

export interface RetryPolicy {
  maxAttempts: number; // 1이면 retry 없음
  baseDelayMs: number;
  maxDelayMs: number;
  jitter: boolean;
}

export interface ProviderExecutionConfig {
  timeoutMs: number;
  retryPolicy: RetryPolicy;
}

export interface OrchestratorOptions {
  providers: AIProvider[];
  providerConfigs: Partial<Record<AIProviderName, ProviderExecutionConfig>>;
  logger?: Logger;
  shouldFallback?: (error: AIProviderError) => boolean;
}

export interface Logger {
  info(message: string, meta?: Record<string, unknown>): void;
  warn(message: string, meta?: Record<string, unknown>): void;
  error(message: string, meta?: Record<string, unknown>): void;
}

const defaultLogger: Logger = {
  info: (message, meta) => console.log(`[INFO] ${message}`, meta ?? {}),
  warn: (message, meta) => console.warn(`[WARN] ${message}`, meta ?? {}),
  error: (message, meta) => console.error(`[ERROR] ${message}`, meta ?? {}),
};

const defaultRetryPolicy: RetryPolicy = {
  maxAttempts: 2,
  baseDelayMs: 300,
  maxDelayMs: 2000,
  jitter: true,
};

const defaultProviderExecutionConfig: ProviderExecutionConfig = {
  timeoutMs: 15_000,
  retryPolicy: defaultRetryPolicy,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeBackoffDelay(
  attempt: number,
  policy: RetryPolicy
): number {
  const expDelay = Math.min(
    policy.baseDelayMs * 2 ** (attempt - 1),
    policy.maxDelayMs
  );

  if (!policy.jitter) return expDelay;

  const jitterFactor = 0.5 + Math.random(); // 0.5x ~ 1.5x
  return Math.floor(expDelay * jitterFactor);
}

function withTimeoutSignal(timeoutMs: number): AbortController {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  // Node.js에서 프로세스 유지 방지
  if (typeof timeout.unref === "function") {
    timeout.unref();
  }

  const originalAbort = controller.abort.bind(controller);
  controller.abort = ((reason?: unknown) => {
    clearTimeout(timeout);
    originalAbort(reason);
  }) as typeof controller.abort;

  return controller;
}

function normalizeUnknownError(
  provider: AIProviderName,
  error: unknown
): AIProviderError {
  if (error instanceof AIProviderError) {
    return error;
  }

  if (error instanceof Error && error.name === "AbortError") {
    return new AIProviderError({
      provider,
      code: "TIMEOUT",
      message: `Provider ${provider} request timed out`,
      retryable: true,
      cause: error,
    });
  }

  if (error instanceof Error) {
    return new AIProviderError({
      provider,
      code: "UNKNOWN",
      message: error.message,
      retryable: false,
      cause: error,
    });
  }

  return new AIProviderError({
    provider,
    code: "UNKNOWN",
    message: "Unknown provider error",
    retryable: false,
    cause: error,
  });
}

function defaultShouldFallback(error: AIProviderError): boolean {
  switch (error.code) {
    case "TIMEOUT":
    case "RATE_LIMIT":
    case "NETWORK":
    case "UPSTREAM":
      return true;
    case "AUTH":
    case "INVALID_REQUEST":
      return false;
    case "UNKNOWN":
    default:
      return error.retryable;
  }
}

async function executeWithRetry(
  provider: AIProvider,
  request: AIRequest,
  config: ProviderExecutionConfig,
  logger: Logger
): Promise<AIResponse> {
  let lastError: AIProviderError | undefined;

  for (let attempt = 1; attempt <= config.retryPolicy.maxAttempts; attempt++) {
    const startedAt = Date.now();
    const controller = withTimeoutSignal(config.timeoutMs);

    try {
      logger.info("Calling AI provider", {
        provider: provider.name,
        model: provider.model,
        attempt,
      });

      const response = await provider.generate(request, controller.signal);

      logger.info("AI provider succeeded", {
        provider: provider.name,
        model: provider.model,
        attempt,
        latencyMs: Date.now() - startedAt,
      });

      controller.abort();
      return response;
    } catch (error) {
      controller.abort();

      const normalized = normalizeUnknownError(provider.name, error);
      lastError = normalized;

      logger.warn("AI provider attempt failed", {
        provider: provider.name,
        model: provider.model,
        attempt,
        code: normalized.code,
        retryable: normalized.retryable,
        message: normalized.message,
      });

      const isLastAttempt = attempt === config.retryPolicy.maxAttempts;
      if (isLastAttempt || !normalized.retryable) {
        throw normalized;
      }

      const delayMs = computeBackoffDelay(attempt, config.retryPolicy);
      await sleep(delayMs);
    }
  }

  throw lastError ?? new AIProviderError({
    provider: provider.name,
    code: "UNKNOWN",
    message: "Provider failed without explicit error",
    retryable: false,
  });
}

export async function generateWithFallback(
  request: AIRequest,
  options: OrchestratorOptions
): Promise<AIResponse> {
  const logger = options.logger ?? defaultLogger;
  const shouldFallback = options.shouldFallback ?? defaultShouldFallback;
  const errors: AIProviderError[] = [];

  for (const provider of options.providers) {
    const config =
      options.providerConfigs[provider.name] ?? defaultProviderExecutionConfig;

    try {
      const response = await executeWithRetry(provider, request, config, logger);
      return response;
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      errors.push(normalized);

      logger.warn("AI provider failed, evaluating fallback", {
        provider: provider.name,
        code: normalized.code,
        retryable: normalized.retryable,
        message: normalized.message,
      });

      if (!shouldFallback(normalized)) {
        logger.error("Fallback aborted due to non-fallbackable error", {
          provider: provider.name,
          code: normalized.code,
          message: normalized.message,
        });
        throw new AIOrchestrationError(
          `Provider ${provider.name} failed and fallback is not allowed`,
          errors
        );
      }
    }
  }

  throw new AIOrchestrationError(
    "All AI providers failed",
    errors
  );
}
