// judge.ts

export type CandidateModel = "openai" | "claude";
export type JudgeWinner = CandidateModel | "tie" | "invalid";

export interface JudgeInput {
  userPrompt: string;
  openaiResponse: string;
  claudeResponse: string;
  taskContext?: string;
}

export interface JudgeResult {
  winner: JudgeWinner;
  confidence: number; // 0.0 ~ 1.0
  scores: {
    openai: number;
    claude: number;
  };
  rationale: string;
  rawJudgeResponse?: string;
}

interface ShuffledCandidates {
  candidateA: {
    original: CandidateModel;
    response: string;
  };
  candidateB: {
    original: CandidateModel;
    response: string;
  };
}

interface JudgeModelOutput {
  winner: "A" | "B" | "tie";
  confidence: number;
  scores: {
    A: number;
    B: number;
  };
  rationale: string;
}

export interface JudgeLLMClient {
  complete(prompt: string): Promise<string>;
}

export interface JudgeOptions {
  minConfidence?: number;
  maxRationaleLength?: number;
  requireNonEmptyResponses?: boolean;
}

const DEFAULT_OPTIONS: Required<JudgeOptions> = {
  minConfidence: 0.55,
  maxRationaleLength: 500,
  requireNonEmptyResponses: true,
};

export class ResponseJudgeService {
  constructor(
    private readonly judgeClient: JudgeLLMClient,
    private readonly options: JudgeOptions = {}
  ) {}

  async judge(input: JudgeInput): Promise<JudgeResult> {
    const opts = { ...DEFAULT_OPTIONS, ...this.options };

    if (opts.requireNonEmptyResponses) {
      const validation = this.validateInput(input);
      if (validation) {
        return validation;
      }
    }

    const shuffled = this.shuffleCandidates(
      input.openaiResponse,
      input.claudeResponse
    );

    const prompt = this.buildJudgePrompt({
      userPrompt: input.userPrompt,
      taskContext: input.taskContext,
      candidateA: shuffled.candidateA.response,
      candidateB: shuffled.candidateB.response,
      maxRationaleLength: opts.maxRationaleLength,
    });

    let rawJudgeResponse = "";
    try {
      rawJudgeResponse = await this.judgeClient.complete(prompt);
      const parsed = this.parseJudgeOutput(rawJudgeResponse);

      if (!parsed) {
        return this.invalidResult(
          "Judge output could not be parsed as valid JSON.",
          rawJudgeResponse
        );
      }

      if (!this.isValidJudgeOutput(parsed)) {
        return this.invalidResult(
          "Judge output failed schema validation.",
          rawJudgeResponse
        );
      }

      const mapped = this.mapBackToOriginalModels(parsed, shuffled);

      if (
        mapped.winner !== "tie" &&
        mapped.winner !== "invalid" &&
        mapped.confidence < opts.minConfidence
      ) {
        return {
          winner: "tie",
          confidence: mapped.confidence,
          scores: mapped.scores,
          rationale: `Judge confidence below threshold (${opts.minConfidence}). ${mapped.rationale}`,
          rawJudgeResponse,
        };
      }

      return {
        ...mapped,
        rawJudgeResponse,
      };
    } catch (error) {
      return this.invalidResult(
        error instanceof Error ? error.message : "Unknown judge error",
        rawJudgeResponse
      );
    }
  }

  private validateInput(input: JudgeInput): JudgeResult | null {
    const openaiEmpty = !input.openaiResponse?.trim();
    const claudeEmpty = !input.claudeResponse?.trim();

    if (openaiEmpty && claudeEmpty) {
      return {
        winner: "invalid",
        confidence: 0,
        scores: { openai: 0, claude: 0 },
        rationale: "Both candidate responses are empty.",
      };
    }

    if (openaiEmpty && !claudeEmpty) {
      return {
        winner: "claude",
        confidence: 1,
        scores: { openai: 0, claude: 1 },
        rationale: "OpenAI response is empty while Claude response is non-empty.",
      };
    }

    if (!openaiEmpty && claudeEmpty) {
      return {
        winner: "openai",
        confidence: 1,
        scores: { openai: 1, claude: 0 },
        rationale: "Claude response is empty while OpenAI response is non-empty.",
      };
    }

    return null;
  }

  private shuffleCandidates(
    openaiResponse: string,
    claudeResponse: string
  ): ShuffledCandidates {
    const swap = Math.random() < 0.5;

    if (swap) {
      return {
        candidateA: { original: "claude", response: claudeResponse },
        candidateB: { original: "openai", response: openaiResponse },
      };
    }

    return {
      candidateA: { original: "openai", response: openaiResponse },
      candidateB: { original: "claude", response: claudeResponse },
    };
  }

  private buildJudgePrompt(params: {
    userPrompt: string;
    taskContext?: string;
    candidateA: string;
    candidateB: string;
    maxRationaleLength: number;
  }): string {
    const { userPrompt, taskContext, candidateA, candidateB, maxRationaleLength } = params;

    return `
You are an impartial evaluator comparing two model responses to the same user request.

Your job is to decide which response is better overall.

Evaluation criteria, in priority order:
1. Instruction following
2. Factual accuracy / non-hallucination
3. Completeness and usefulness
4. Clarity and organization
5. Safety and appropriateness
6. Conciseness (only if all else is similar)

Important rules:
- Do not prefer a response for style alone.
- Ignore verbosity unless it improves usefulness.
- Penalize factual errors, unsupported claims, and failure to answer the request.
- If both responses are similarly good, return "tie".
- Output ONLY valid JSON. No markdown, no code fences, no extra text.

Required JSON format:
{
  "winner": "A" | "B" | "tie",
  "confidence": number,
  "scores": {
    "A": number,
    "B": number
  },
  "rationale": string
}

Constraints:
- confidence must be between 0 and 1
- scores.A and scores.B must be between 0 and 10
- rationale must be concise and under ${maxRationaleLength} characters

${taskContext ? `Task context:\n${taskContext}\n` : ""}

User request:
${userPrompt}

Response A:
${candidateA}

Response B:
${candidateB}
`.trim();
  }

  private parseJudgeOutput(raw: string): JudgeModelOutput | null {
    const trimmed = raw.trim();

    // 1) direct JSON parse
    try {
      return JSON.parse(trimmed) as JudgeModelOutput;
    } catch {
      // continue
