function getDimensionScore(entry: ScoreboardEntry, name: string): number {
  return entry.dimensions.find((d) => d.name === name)?.score ?? 0;
}

function defaultTieBreaker(a: ScoreboardEntry, b: ScoreboardEntry): number {
  if (b.totalScore !== a.totalScore) {
    return b.totalScore - a.totalScore;
  }

  const successDiff = getDimensionScore(b, "success") - getDimensionScore(a, "success");
  if (successDiff !== 0) return successDiff;

  const qualityDiff =
    getDimensionScore(b, "contentQuality") - getDimensionScore(a, "contentQuality");
  if (qualityDiff !== 0) return qualityDiff;

