  costUsd?: number;
  status: "success" | "error" | "timeout";
  errorMessage?: string;
  metadata?: Record<string, unknown>;
}

export interface ScoreDimensionResult {
  name: string;
  score: number; // normalized 0~1
  weight: number;
  weightedScore: number;
  reason?: string;
}

export interface ScoreboardEntry {
  provider: ProviderName;
  response: ProviderResponse;
  dimensions: ScoreDimensionResult[];
  totalScore: number;
  rank?: number;
}

export interface WinnerResult {
  winner: ScoreboardEntry | null;
  scoreboard: ScoreboardEntry[];
  reason?: string;
}

export interface EvaluationContext {
  userPrompt: string;
  maxAcceptableLatencyMs?: number;
  maxAcceptableCostUsd?: number;
  preferredProviders?: ProviderName[];
  requireNonEmptyContent?: boolean;
}

export interface ScoreRule {
  name: string;
  weight: number;
  evaluate: (
    response: ProviderResponse,
    context: EvaluationContext
  ) => Omit<ScoreDimensionResult, "weight" | "weightedScore">;
}

function clamp01(value: number): number {
  if (Number.isNaN(value)) return 0;
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}

/**
 * Rule 1: 응답 성공 여부
 * - success면 1
 * - error/timeout이면 0
 */
export const successRule: ScoreRule = {
  name: "success",
  weight: 0.35,
  evaluate: (response) => {
    const score = response.status === "success" ? 1 : 0;
    return {
      name: "success",
      score,
      reason:
        response.status === "success"
          ? "Provider responded successfully"
          : `Provider failed with status=${response.status}`,
    };
  },
};

/**
 * Rule 2: 내용 품질의 아주 단순한 휴리스틱
 * 실제 production에서는 LLM-as-a-judge, schema validation, business rule validation 등으로 대체 가능
 */
export const contentQualityRule: ScoreRule = {
  name: "contentQuality",
  weight: 0.30,
  evaluate: (response, context) => {
    if (response.status !== "success") {
      return {
        name: "contentQuality",
        score: 0,
        reason: "No quality score because response was not successful",
      };
    }

    const content = response.content?.trim() ?? "";
    if (context.requireNonEmptyContent && content.length === 0) {
      return {
        name: "contentQuality",
        score: 0,
        reason: "Empty content",
      };
    }

    // 단순 예시:
    // - 너무 짧으면 낮은 점수
    // - 적당한 길이면 높은 점수
    // - 지나치게 길면 약간 감점
    let score = 0;

    if (content.length === 0) {
      score = 0;
    } else if (content.length < 20) {
      score = 0.3;
    } else if (content.length < 100) {
      score = 0.7;
    } else if (content.length < 2000) {
      score = 1.0;
    } else {
      score = 0.8;
    }

    // 프롬프트 키워드 포함 여부 같은 간단한 relevance 체크
    const promptWords = context.userPrompt
      .toLowerCase()
      .split(/\s+/)
      .filter((w) => w.length >= 4);

    const contentLower = content.toLowerCase();
    const matched = promptWords.filter((w) => contentLower.includes(w)).length;
    const relevanceBoost =
      promptWords.length > 0 ? Math.min(0.2, matched / promptWords.length) : 0;

    score = clamp01(score * 0.8 + relevanceBoost);

    return {
      name: "contentQuality",
      score,
      reason: `Content length=${content.length}, matchedPromptWords=${matched}`,
    };
  },
};

/**
 * Rule 3: latency
 * - maxAcceptableLatencyMs 기준으로 점수화
 */
export const latencyRule: ScoreRule = {
  name: "latency",
  weight: 0.20,
  evaluate: (response, context) => {
    if (response.status !== "success") {
      return {
        name: "latency",
        score: 0,
        reason: "No latency score because response was not successful",
      };
    }

    const maxLatency = context.maxAcceptableLatencyMs ?? 5000;
    const latency = response.latencyMs;

    // latency가 0이면 최고점, maxLatency 이상이면 0점에 가까움
    const score = clamp01(1 - latency / maxLatency);

    return {
      name: "latency",
      score,
      reason: `latencyMs=${latency}, maxAcceptableLatencyMs=${maxLatency}`,
    };
  },
};

/**
 * Rule 4: cost
 * - maxAcceptableCostUsd 기준으로 점수화
 */
export const costRule: ScoreRule = {
  name: "cost",
  weight: 0.15,
  evaluate: (response, context) => {
    if (response.status !== "success") {
      return {
        name: "cost",
        score: 0,
        reason: "No cost score because response was not successful",
      };
    }

    const maxCost = context.maxAcceptableCostUsd ?? 0.05;
    const cost = response.costUsd ?? maxCost;

    const score = clamp01(1 - cost / maxCost);

    return {
      name: "cost",
      score,
      reason: `costUsd=${cost}, maxAcceptableCostUsd=${maxCost}`,
    };
  },
};

/**
 * Rule 5: preferred provider bonus
 * - 특정 provider를 선호할 경우 약간의 가산점
 */
export const providerPreferenceRule: ScoreRule = {
  name: "providerPreference",
  weight: 0.05,
  evaluate: (response, context) => {
    const preferred = context.preferredProviders ?? [];
    const score = preferred.includes(response.provider) ? 1 : 0;
    return {
      name: "providerPreference",
      score,
      reason: preferred.includes(response.provider)
        ? `${response.provider} is preferred`
        : `${response.provider} is not preferred`,
    };
  },
};

export interface ScoreboardOptions {
  rules?: ScoreRule[];
  /**
   * tie-breaker:
   * 1) totalScore desc
   * 2) success score desc
   * 3) contentQuality desc
   * 4) latency asc
   * 5) cost asc
   */
