```ts
import { ExecutionResult, Plan, PlanStep, StepExecutionResult } from "./types";
import { Logger } from "./logger";

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  constructor(private readonly logger: Logger) {}

  async execute(plan: Plan): Promise<ExecutionResult> {
    const stepResults: StepExecutionResult[] = [];

    let previousOutput: unknown = undefined;

    for (const step of plan.steps) {
      const result = await this.executeStep(step, previousOutput);
      stepResults.push(result);

      if (!result.success) {
        return {
          planId: plan.planId,
          stepResults,
          success: false,
        };
      }

      previousOutput = result.output;
    }

    return {
      planId: plan.planId,
      stepResults,
      success: true,
    };
  }

  private async executeStep(
    step: PlanStep,
    previousOutput: unknown
  ): Promise<StepExecutionResult> {
    const startedAt = new Date().toISOString();

    try {
      this.logger.info("Executing step", {
        stepId: step.id,
        action: step.action,
      });

      let output: unknown;

      switch (step.action) {
        case "fetch_data":
          output = await this.fetchData(step.payload);
          break;
        case "transform_data":
          output = await this.transformData(previousOutput);
          break;
        case "summarize":
          output = await this.summarize(previousOutput);
          break;
        default: {
          const exhaustiveCheck: never = step.action;
          throw new Error(`Unsupported action: ${exhaustiveCheck}`);
        }
      }

      return {
        stepId: step.id,
        success: true,
        output,
        startedAt,
        finishedAt: new Date().toISOString(),
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unknown error";

      this.logger.error("Step execution failed", {
        stepId: step.id,
        error: message,
      });

      return {
        stepId: step.id,
        success: false,
        error: message,
        startedAt,
        finishedAt: new Date().toISOString(),
      };
    }
  }

  private async fetchData(payload?: Record<string, unknown>): Promise<unknown> {
    await this.simulateDelay(200);

    const query = payload?.query;
    if (!query || typeof query !== "string") {
      throw new Error("Invalid query payload");
    }

    return {
      source: "mock-datasource",
      items: [
        `raw item 1 for: ${query}`,
        `raw item 2 for: ${query}`,
        `raw item 3 for: ${query}`,
      ],
    };
  }

  private async transformData(input: unknown): Promise<unknown> {
    await this.simulateDelay(150);

    if (
      !input ||
      typeof input !== "object" ||
      !("items" in input) ||
      !Array.isArray((input as { items: unknown[] }).items)
    ) {
      throw new Error("Invalid input for transform_data");
    }

    const items = (input as { items: string[] }).items;

    return {
      transformedItems: items.map((item, index) => ({
        id: index + 1,
        text: item.toUpperCase(),
      })),
    };
  }

  private async summarize(input: unknown): Promise<unknown> {
    await this.simulateDelay(100);

    if (
      !input ||
      typeof input !== "object" ||
      !("transformedItems" in input) ||
      !Array.isArray((input as { transformedItems: unknown[] }).transformedItems)
    ) {
      throw new Error("Invalid input for summarize");
    }

    const transformedItems = (input as { transformedItems: Array<{ id: number; text: string }> }).transformedItems;

    return {
      summary: `Processed ${transformedItems.length} items`,
      preview: transformedItems.slice(0, 2),
    };
  }

  private async simulateDelay(ms: number): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, ms));
  }
}
