import { ExecutionResult, JudgeResult, Plan } from "./types";

export interface Judge {
  evaluate(plan: Plan, execution: ExecutionResult): Promise<JudgeResult>;
}

export class SimpleJudge implements Judge {
  async evaluate(plan: Plan, execution: ExecutionResult): Promise<JudgeResult> {
    if (!execution.success) {
      return {
        decision: "replan",
        reason: "Execution failed. A revised plan may be required.",
      };
    }

    const executedStepCount = execution.stepResults.length;
    const plannedStepCount = plan.steps.length;

    if (executedStepCount !== plannedStepCount) {
      return {
        decision: "replan",
        reason: "Not all planned steps were executed.",
      };
    }

    const lastStep = execution.stepResults[execution.stepResults.length - 1];
    if (!lastStep?.output) {
      return {
        decision: "rejected",
        reason: "Final output is missing.",
      };
    }

    return {
      decision: "approved",
      reason: "Execution completed successfully and produced final output.",
    };
  }
}
