import { Executor } from "./executor";
import { Judge } from "./judge";
import { Logger } from "./logger";
import { Planner } from "./planner";
import { OrchestrationResult, TaskInput } from "./types";

export class Orchestrator {
  constructor(
    private readonly planner: Planner,
    private readonly executor: Executor,
    private readonly judge: Judge,
    private readonly logger: Logger
  ) {}

  async run(input: TaskInput): Promise<OrchestrationResult> {
    this.logger.info("Orchestration started", {
      requestId: input.requestId,
      userGoal: input.userGoal,
    });

    const plan = await this.planner.createPlan(input);

    this.logger.info("Plan created", {
      requestId: input.requestId,
      planId: plan.planId,
      stepCount: plan.steps.length,
    });

    const execution = await this.executor.execute(plan);

    this.logger.info("Execution completed", {
      requestId: input.requestId,
      planId: plan.planId,
      success: execution.success,
    });

    const judgeResult = await this.judge.evaluate(plan, execution);

    this.logger.info("Judge completed", {
      requestId: input.requestId,
      decision: judgeResult.decision,
      reason: judgeResult.reason,
    });

    return {
      requestId: input.requestId,
      input,
      plan,
      execution,
      judge: judgeResult,
    };
  }
}
