## 11. Router에서 fallback 처리

### `src/router/provider-router.ts`

```ts
import { Provider } from '../providers/provider.interface';
import { NotificationRequest, NotificationResult } from '../types/notification';

export class ProviderRouter {
  private readonly providers: Provider[];

  constructor(providers: Provider[]) {
    if (providers.length === 0) {
      throw new Error('At least one provider must be registered');
    }

    this.providers = [...providers].sort((a, b) => b.priority - a.priority);
  }

  getProviders(request: NotificationRequest): Provider[] {
    return this.providers.filter((p) => p.supports(request.channel));
  }

  async route(request: NotificationRequest): Promise<NotificationResult> {
    const matchedProviders = this.getProviders(request);

    if (matchedProviders.length === 0) {
      throw new Error(`No provider found for channel: ${request.channel}`);
    }

    let lastError: unknown;

    for (const provider of matchedProviders) {
      try {
        return await provider.send(request);
      } catch (error) {
        lastError = error;
        console.error(`[ProviderRouter] provider failed: ${provider.name}`, error);
      }
    }

    throw new Error(
      `All providers failed for channel=${request.channel}, lastError=${String(lastError)}`
    );
  }
}
```

