## 3. 공통 유틸: timeout, sleep, retry 판별

```ts
// ai/utils.ts
import { AIProviderError } from "./types";

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function withTimeoutSignal(timeoutMs?: number, parentSignal?: AbortSignal): AbortSignal | undefined {
  if (!timeoutMs && !parentSignal) return undefined;

  const controller = new AbortController();

  const onAbort = () => controller.abort(parentSignal?.reason ?? new Error("Parent signal aborted"));
  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort(parentSignal.reason);
      return controller.signal;
    }
    parentSignal.addEventListener("abort", onAbort, { once: true });
  }

  let timeoutId: NodeJS.Timeout | undefined;
  if (timeoutMs && timeoutMs > 0) {
    timeoutId = setTimeout(() => {
      controller.abort(new Error(`Timed out after ${timeoutMs}ms`));
    }, timeoutMs);
  }

  controller.signal.addEventListener(
    "abort",
    () => {
      if (timeoutId) clearTimeout(timeoutId);
      if (parentSignal) parentSignal.removeEventListener("abort", onAbort);
    },
    { once: true }
  );

  return controller.signal;
}

export function isAbortError(err: unknown): boolean {
  return err instanceof Error && (
    err.name === "AbortError" ||
    err.message.includes("aborted") ||
    err.message.includes("Timed out")
  );
}

export function computeBackoffMs(attempt: number, baseMs = 300, maxMs = 3000): number {
  const exp = Math.min(maxMs, baseMs * 2 ** (attempt - 1));
  const jitter = Math.floor(Math.random() * 100);
  return exp + jitter;
}

export function normalizeUnknownError(provider: string, err: unknown): AIProviderError {
  if (err instanceof AIProviderError) return err;

  if (isAbortError(err)) {
    return new AIProviderError({
      provider,
      code: "TIMEOUT",
      message: err instanceof Error ? err.message : "Request timed out or aborted",
      retryable: true,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    code: "UNKNOWN",
    message: err instanceof Error ? err.message : "Unknown provider error",
    retryable: false,
    cause: err,
  });
}
```

