### 4.1 OpenAI 스타일 provider 예시

```ts
// ai/providers/openai-provider.ts
import {
  AIProvider,
  GenerateRequest,
  GenerateResult,
  ProviderContext,
  AIProviderError,
} from "../types";
import { normalizeUnknownError, withTimeoutSignal } from "../utils";

interface OpenAIProviderOptions {
  apiKey: string;
  baseUrl?: string;
  defaultModel: string;
}

export class OpenAIProvider implements AIProvider {
  public readonly name = "openai";
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly defaultModel: string;

  constructor(options: OpenAIProviderOptions) {
    this.apiKey = options.apiKey;
    this.baseUrl = options.baseUrl ?? "https://api.openai.com/v1";
    this.defaultModel = options.defaultModel;
  }

  async generate(request: GenerateRequest, ctx?: ProviderContext): Promise<GenerateResult> {
    const signal = withTimeoutSignal(ctx?.timeoutMs, ctx?.signal);

    try {
      const response = await fetch(`${this.baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${this.apiKey}`,
        },
        signal,
        body: JSON.stringify({
          model: request.model ?? this.defaultModel,
          messages: request.messages,
          temperature: request.temperature,
          max_tokens: request.maxTokens,
        }),
      });

      if (!response.ok) {
        const text = await response.text().catch(() => "");
        throw this.mapHttpError(response.status, text);
      }

      const data = await response.json();

      const content = data?.choices?.[0]?.message?.content;
      if (!content || typeof content !== "string") {
        throw new AIProviderError({
          provider: this.name,
          code: "INTERNAL",
          message: "Invalid response shape from OpenAI provider",
          retryable: false,
          cause: data,
        });
      }

      return {
        provider: this.name,
        model: data.model ?? request.model ?? this.defaultModel,
        content,
        finishReason: data?.choices?.[0]?.finish_reason,
        usage: {
          inputTokens: data?.usage?.prompt_tokens,
          outputTokens: data?.usage?.completion_tokens,
          totalTokens: data?.usage?.total_tokens,
        },
        raw: data,
      };
    } catch (err) {
      throw normalizeUnknownError(this.name, err);
    }
  }

  private mapHttpError(status: number, body: string): AIProviderError {
    if (status === 400) {
      return new AIProviderError({
        provider: this.name,
        code: "BAD_REQUEST",
        message: `OpenAI bad request: ${body}`,
        retryable: false,
        status,
      });
    }
    if (status === 401 || status === 403) {
      return new AIProviderError({
        provider: this.name,
        code: "AUTH",
        message: `OpenAI auth error: ${body}`,
        retryable: false,
        status,
      });
    }
    if (status === 429) {
      return new AIProviderError({
        provider: this.name,
        code: "RATE_LIMIT",
        message: `OpenAI rate limited: ${body}`,
        retryable: true,
        status,
      });
    }
    if (status >= 500) {
      return new AIProviderError({
        provider: this.name,
        code: "UNAVAILABLE",
        message: `OpenAI server error: ${body}`,
        retryable: true,
        status,
      });
    }

    return new AIProviderError({
      provider: this.name,
      code: "UNKNOWN",
      message: `OpenAI unexpected error (${status}): ${body}`,
      retryable: false,
      status,
    });
  }
}
```

