# 4. 규칙 기반 전처리

LLM judge를 호출하기 전에 명백한 케이스는 빠르게 처리하는 것이 좋습니다.

예:
- 한쪽 응답이 비어 있음
- 한쪽이 “죄송하지만…”만 반복
- 한쪽이 지나치게 짧고 다른 쪽은 충분히 답변
- safety flag가 심각함

```ts
export interface PreFilterDecision {
  decided: boolean;
  result?: JudgeResult;
}

export class RuleBasedPreFilter {
  evaluate(req: JudgeRequest): PreFilterDecision {
    const openaiText = req.openai.content.trim();
    const claudeText = req.claude.content.trim();

    if (!openaiText && !claudeText) {
      return {
        decided: true,
        result: {
          winner: "tie",
          confidence: 1,
          summary: "Both responses are empty.",
          dimensions: [],
          finalScores: { openai: 0, claude: 0 },
          needsHumanReview: true,
        },
      };
    }

    if (!openaiText) {
      return {
        decided: true,
        result: {
          winner: "claude",
          confidence: 0.98,
          summary: "OpenAI response is empty.",
          dimensions: [],
          finalScores: { openai: 0, claude: 10 },
          needsHumanReview: false,
        },
      };
    }

    if (!claudeText) {
      return {
        decided: true,
        result: {
          winner: "openai",
          confidence: 0.98,
          summary: "Claude response is empty.",
          dimensions: [],
          finalScores: { openai: 10, claude: 0 },
          needsHumanReview: false,
        },
      };
    }

    const severeOpenAiSafety = req.openai.safetyFlags?.includes("severe") ?? false;
    const severeClaudeSafety = req.claude.safetyFlags?.includes("severe") ?? false;

    if (severeOpenAiSafety && !severeClaudeSafety) {
      return {
        decided: true,
        result: {
          winner: "claude",
          confidence: 0.95,
          summary: "OpenAI response has severe safety flags.",
          dimensions: [],
          finalScores: { openai: 0, claude: 10 },
          needsHumanReview: false,
        },
      };
    }

    if (severeClaudeSafety && !severeOpenAiSafety) {
      return {
        decided: true,
        result: {
          winner: "openai",
          confidence: 0.95,
          summary: "Claude response has severe safety flags.",
          dimensions: [],
          finalScores: { openai: 10, claude: 0 },
          needsHumanReview: false,
        },
      };
    }

    return { decided: false };
  }
}
```

