      "name": "relevance" | "correctness" | "completeness" | "clarity" | "safety" | "code_quality",
      "A": number,
      "B": number,
      "rationale": string
    }
  ]
}

User request:
"""${userPrompt}"""

Response A:
"""${responseA}"""

Response B:
"""${responseB}"""
`.trim();
}
