# 2) 유틸 함수

점수 clamp, 안전한 숫자 처리, tie-breaker 비교 등을 분리합니다.

```ts
// scoreboard-utils.ts

export function clamp(value: number, min = 0, max = 1): number {
  if (Number.isNaN(value)) return min;
  return Math.max(min, Math.min(max, value));
}

export function safeNumber(value: unknown, fallback = 0): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

export function compareScorecards(a: { totalWeightedScore: number; success: boolean; latencyMs: number; costUsd?: number }, b: { totalWeightedScore: number; success: boolean; latencyMs: number; costUsd?: number }): number {
  // 1. 총점 높은 순
  if (b.totalWeightedScore !== a.totalWeightedScore) {
    return b.totalWeightedScore - a.totalWeightedScore;
  }

  // 2. success=true 우선
  if (a.success !== b.success) {
    return Number(b.success) - Number(a.success);
  }

  // 3. latency 낮은 순
  if (a.latencyMs !== b.latencyMs) {
    return a.latencyMs - b.latencyMs;
  }

  // 4. cost 낮은 순
  const aCost = a.costUsd ?? Number.POSITIVE_INFINITY;
  const bCost = b.costUsd ?? Number.POSITIVE_INFINITY;
  if (aCost !== bCost) {
    return aCost - bCost;
  }

  return 0;
}
```

