```ts
// score-rules.ts

import { ProviderResponse, ScoreContext, ScoreRule } from "./scoreboard";
import { clamp } from "./scoreboard-utils";

export function successRule(weight = 5): ScoreRule {
  return {
    name: "success",
    weight,
    description: "응답 성공 여부",
    score: (response: ProviderResponse) => (response.success ? 1 : 0),
    minScore: 0,
    maxScore: 1,
  };
}

export function latencyRule(options?: {
  weight?: number;
  idealMs?: number;
  maxMs?: number;
}): ScoreRule {
  const weight = options?.weight ?? 3;
  const idealMs = options?.idealMs ?? 300;
  const maxMs = options?.maxMs ?? 3000;

  return {
    name: "latency",
    weight,
    description: `latency가 ideal(${idealMs}ms)에 가까울수록 높은 점수`,
    score: (response: ProviderResponse) => {
      if (!response.success) return 0;
      const latency = response.latencyMs;
      if (latency <= idealMs) return 1;
      if (latency >= maxMs) return 0;
      const normalized = 1 - (latency - idealMs) / (maxMs - idealMs);
      return clamp(normalized, 0, 1);
    },
    minScore: 0,
    maxScore: 1,
  };
}

export function costRule(options?: {
  weight?: number;
  idealCostUsd?: number;
  maxCostUsd?: number;
}): ScoreRule {
  const weight = options?.weight ?? 2;
  const idealCostUsd = options?.idealCostUsd ?? 0.001;
  const maxCostUsd = options?.maxCostUsd ?? 0.05;

  return {
    name: "cost",
    weight,
    description: "비용이 낮을수록 높은 점수",
    score: (response: ProviderResponse) => {
      if (!response.success) return 0;
      const cost = response.costUsd;
      if (cost == null) return 0.5; // 비용 정보 없으면 중립
      if (cost <= idealCostUsd) return 1;
      if (cost >= maxCostUsd) return 0;
      const normalized = 1 - (cost - idealCostUsd) / (maxCostUsd - idealCostUsd);
      return clamp(normalized, 0, 1);
    },
    minScore: 0,
    maxScore: 1,
  };
}

export function keywordCoverageRule(weight = 4): ScoreRule {
  return {
    name: "keyword_coverage",
    weight,
    description: "expectedKeywords 포함 비율",
    score: (response: ProviderResponse, context: ScoreContext) => {
      if (!response.success) return 0;
      const keywords = context.expectedKeywords ?? [];
      if (keywords.length === 0) return 1;

      const text = String(response.rawText ?? response.output ?? "").toLowerCase();
      if (!text) return 0;

      const matched = keywords.filter((kw) => text.includes(kw.toLowerCase())).length;
      return clamp(matched / keywords.length, 0, 1);
    },
    minScore: 0,
    maxScore: 1,
  };
}

export function schemaValidityRule(weight = 5): ScoreRule {
  return {
    name: "schema_validity",
    weight,
    description: "output이 schemaValidator를 통과하는지",
    score: (response: ProviderResponse, context: ScoreContext) => {
      if (!response.success) return 0;
      if (!context.schemaValidator) return 1;
      return context.schemaValidator(response.output) ? 1 : 0;
    },
    minScore: 0,
    maxScore: 1,
  };
}

export function textLengthHeuristicRule(options?: {
  weight?: number;
  minLength?: number;
  idealLength?: number;
  maxLength?: number;
}): ScoreRule {
  const weight = options?.weight ?? 1;
  const minLength = options?.minLength ?? 20;
  const idealLength = options?.idealLength ?? 200;
  const maxLength = options?.maxLength ?? 2000;

  return {
    name: "text_length_heuristic",
    weight,
    description: "너무 짧거나 너무 긴 응답을 감점하는 휴리스틱",
    score: (response: ProviderResponse) => {
      if (!response.success) return 0;
      const text = String(response.rawText ?? response.output ?? "");
      const len = text.trim().length;

      if (len < minLength) return 0;
      if (len === idealLength) return 1;
      if (len > maxLength) return 0.2;

      if (len < idealLength) {
        return clamp((len - minLength) / (idealLength - minLength), 0, 1);
      }

      const decay = 1 - (len - idealLength) / (maxLength - idealLength);
      return clamp(decay, 0.2, 1);
    },
    minScore: 0,
    maxScore: 1,
  };
}
