export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput): Promise<Plan> {
    const steps: PlanStep[] = [
      {
        id: "step-1",
        type: "fetch_data",
        description: `Fetch data relevant to goal: ${input.userGoal}`,
        payload: {
          query: input.userGoal
        }
      },
      {
        id: "step-2",
        type: "transform_data",
        description: "Transform fetched data into structured insights"
      },
      {
        id: "step-3",
        type: "summarize",
        description: "Summarize the transformed insights"
