# 7) Planner: `src/planner.ts`

입력을 보고 plan을 생성합니다.
지금은 단순 규칙 기반이지만, 나중에 LLM planner로 교체하기 쉽도록 인터페이스를 둡니다.

```ts
import { Plan, PlanStep, WorkflowInput } from "./types";
import { nowIso } from "./utils";

export interface Planner {
  createPlan(input: WorkflowInput): Promise<Plan>;
}

export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput): Promise<Plan> {
    const steps: PlanStep[] = [
      {
        id: "step-1",
        type: "fetch_data",
        description: `Fetch data relevant to goal: ${input.userGoal}`,
        payload: {
          query: input.userGoal
        }
      },
      {
        id: "step-2",
        type: "transform_data",
        description: "Transform fetched data into structured insights"
      },
      {
        id: "step-3",
        type: "summarize",
        description: "Summarize the transformed insights"
      }
    ];

    return {
      planId: `plan-${input.requestId}`,
      steps,
      createdAt: nowIso()
    };
  }
}
```

