# 8) Executor: `src/executor.ts`

각 step을 실제 수행합니다.
여기서는 예시로 mock 작업을 수행하지만, 외부 API 호출/DB 조회/LLM 호출로 쉽게 바꿀 수 있습니다.

```ts
import {
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types";
import { nowIso, retry, sleep, toErrorMessage, withTimeout } from "./utils";

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  async execute(plan: Plan): Promise<ExecutionResult> {
    const startedAt = nowIso();
    const stepResults: StepExecutionResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeStepSafely(step, stepResults);
      stepResults.push(result);

      // 이전 step 실패 시 이후 step을 skip하는 정책 예시
      if (result.status === "failed") {
        for (const remainingStep of plan.steps.slice(stepResults.length)) {
          stepResults.push({
            stepId: remainingStep.id,
            type: remainingStep.type,
            status: "skipped",
            startedAt: nowIso(),
            finishedAt: nowIso(),
            error: {
              message: "Skipped due to previous step failure",
              retryable: false
            }
          });
        }
        break;
      }
    }

    const hasFailure = stepResults.some((r) => r.status === "failed");
    const hasSuccess = stepResults.some((r) => r.status === "success");

    const status: ExecutionResult["status"] = hasFailure
      ? hasSuccess
        ? "partial_failure"
        : "failed"
      : "success";

    return {
      planId: plan.planId,
      status,
      stepResults,
      startedAt,
      finishedAt: nowIso()
    };
  }

